import numpy as np

def sampled_mellin_exp(sigma: float, omega: float, count: int = 40001) -> complex:
    """Approximate the Mellin transform of exp(-x) using x=exp(u)."""
    u = np.linspace(-12.0, 5.0, count)
    x = np.exp(u)
    integrand = np.exp(-x) * np.exp((sigma + 1j*omega) * u)
    trap = getattr(np, "trapezoid", np.trapz)
    return complex(trap(integrand, u))

for omega in (-8.0, -4.0, 0.0, 4.0, 8.0):
    print(f"M(1+{omega}i) = {sampled_mellin_exp(1.0, omega)}")

